EXEC GENERIC.Pr_UpdateEventLog
 @EventTypeID,
 @InfoEventSeverityID,
 @ModuleID,
 'Load MedSupp TransCentra batch process completed successfully.'

IF OBJECT_ID('Invoice.MedSupp_BatchSummary_TEMP') IS NOT NULL DROP TABLE Invoice.MedSupp_BatchSummary_TEMP

SET NOCOUNT OFF

DECLARE 
 @Continue BIT = 1, 
 @ReadyBatchStatusID INT,  
 @EventTypeId INT, 
 @InfoEventSeverityId INT,
 @CriticalEventSeverityId INT, 
 @ModuleId INT, 
 @BatchCategoryID INT

SET @ReadyBatchStatusID = @User::ReadyBatchStatusID
SET @EventTypeId = @User::EventTypeID
SET @InfoEventSeverityId = @User::InfoEventSeverityID 
SET @CriticalEventSeverityId = @User::CriticalEventSeverityID
SET @ModuleId = @User::ModuleID 
SET @BatchCategoryID = @User::BatchCategoryID

IF NOT EXISTS(
 SELECT 1 
 FROM ( 
  SELECT 
   ROW_NUMBER() OVER (ORDER BY b.BatchId DESC) AS RowNumber, 
   b.BatchStatusId
  FROM Invoice.Batch b 
  INNER JOIN Invoice.BatchStatus bs 
   ON b.BatchStatusId = bs.BatchStatusId 
  WHERE bs.BatchStatus NOT IN ('Complete', 'Error', 'Re-Ran')
   AND b.BatchCategoryID = @BatchCategoryID
 ) x 
 WHERE x.RowNumber = 1 
  AND x.BatchStatusId = @ReadyBatchStatusID
) 
BEGIN 
 SET @Continue = 0

 EXEC GENERIC.Pr_UpdateEventLog
  @EventTypeId,
  @CriticalEventSeverityId,
  @ModuleId,
  'No records found to generate MedSupp Transcentra file.'

 EXEC GENERIC.Pr_UpdateEventLog
  @EventTypeId,
  @InfoEventSeverityId,
  @ModuleId,
  'Package MedSupp Billing batch- End'
END 

SELECT @Continue

IF OBJECT_ID('Invoice.MedSupp_BatchSummary_TEMP') IS NOT NULL DROP TABLE Invoice.MedSupp_BatchSummary_TEMP

SET NOCOUNT OFF

EXEC GENERIC.Pr_UpdateEventLog
 @EventTypeID,
 @CriticalEventSeverityID,
 @ModuleID,
 'Load MedSupp TC Batch processs FAILED!'


RAISERROR('Load MedSupp  TC Batch processs FAILED! See EventLog for details.', 16, 1)

EXEC GENERIC.Pr_UpdateEventLog
	@EventTypeID, 
	@InfoEventSeverityID, 
	@ModuleID, 
	'Execute SQL Task to start TC Invoice Balancing report subscription started.'

EXEC ReportServer.dbo.AddEvent
	@EventType='TimedSubscription',
	@EventData=@SsrsSubscriptionId

EXEC GENERIC.Pr_UpdateEventLog
 @EventTypeID, 
 @InfoEventSeverityID, 
 @ModuleID, 
 'Execute SQL Task to start TC Invoice Balancing report subscription complete.'

DECLARE @EventDesc NVARCHAR(MAX)

SET @EventDesc = 'Execute SQL Task to start TC Invoice Balancing report subscription FAILED!'

EXEC GENERIC.Pr_UpdateEventLog
 @EventTypeID, 
 @CriticalEventSeverityID, 
 @ModuleID, 
 @EventDesc 


RAISERROR(@EventDesc, 16, 1)
